DO $$DECLARE  has_perms BOOLEAN;BEGIN  has_perms := EXISTS (    SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'permissions'  );  IF has_perms THEN    ALTER TABLE public.permissions DROP CONSTRAINT IF EXISTS permission_requests_workflow_type_check;    ALTER TABLE public.permissions DROP CONSTRAINT IF EXISTS permissions_workflow_type_check;    ALTER TABLE public.permissions DROP CONSTRAINT IF EXISTS permission_requests_check;    ALTER TABLE public.permissions ADD CONSTRAINT permissions_workflow_type_check      CHECK (workflow_type IN ('hostel','exam','memo','staff_leave','lab_access'));  ELSIF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'permission_requests') THEN    ALTER TABLE public.permission_requests DROP CONSTRAINT IF EXISTS permission_requests_workflow_type_check;    ALTER TABLE public.permission_requests ADD CONSTRAINT permission_requests_workflow_type_check      CHECK (workflow_type IN ('hostel','exam','memo','staff_leave','lab_access'));  END IF;END $$;DO $$BEGIN  ALTER TABLE public.custom_reasons DROP CONSTRAINT IF EXISTS custom_reasons_workflow_type_check;  ALTER TABLE public.custom_reasons ADD CONSTRAINT custom_reasons_workflow_type_check    CHECK (workflow_type IN ('hostel','exam','memo','staff_leave','lab_access'));END $$;DO $$BEGIN  ALTER TABLE public.document_templates DROP CONSTRAINT IF EXISTS document_templates_workflow_type_check;  ALTER TABLE public.document_templates ADD CONSTRAINT document_templates_workflow_type_check    CHECK (workflow_type IN ('hostel','exam','memo','staff_leave','lab_access'));END $$;UPDATE public.permissions SET status = 'CANCELLED' WHERE status = 'EXPIRED';UPDATE public.permissions SET status = 'ESCALATED' WHERE status = 'DISPUTED';DO $$DECLARE  has_perms BOOLEAN;BEGIN  has_perms := EXISTS (    SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'permissions'  );  IF has_perms THEN    ALTER TABLE public.permissions DROP CONSTRAINT IF EXISTS permission_requests_status_check;    ALTER TABLE public.permissions DROP CONSTRAINT IF EXISTS permissions_status_check;    ALTER TABLE public.permissions DROP CONSTRAINT IF EXISTS permission_requests_check;    ALTER TABLE public.permissions ADD CONSTRAINT permissions_status_check      CHECK (status IN ('PENDING','APPROVED','REJECTED','ESCALATED','COMPLETED','CANCELLED'));  ELSIF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'permission_requests') THEN    ALTER TABLE public.permission_requests DROP CONSTRAINT IF EXISTS permission_requests_status_check;    ALTER TABLE public.permission_requests ADD CONSTRAINT permission_requests_status_check      CHECK (status IN ('PENDING','APPROVED','REJECTED','ESCALATED','COMPLETED','CANCELLED'));  END IF;END $$;CREATE OR REPLACE FUNCTION public.enforce_permission_transitions()RETURNS triggerLANGUAGE plpgsqlAS $function$DECLARE  v_allowed text[];BEGIN  IF NEW.status = OLD.status THEN    RETURN NEW;  END IF;  CASE OLD.status    WHEN 'PENDING'   THEN v_allowed := ARRAY['APPROVED', 'REJECTED', 'ESCALATED', 'COMPLETED', 'CANCELLED'];    WHEN 'ESCALATED' THEN v_allowed := ARRAY['APPROVED', 'REJECTED', 'COMPLETED', 'CANCELLED'];    WHEN 'APPROVED'  THEN v_allowed := ARRAY['COMPLETED'];    WHEN 'REJECTED'  THEN v_allowed := ARRAY[]::text[];    WHEN 'COMPLETED' THEN v_allowed := ARRAY[]::text[];    WHEN 'CANCELLED' THEN v_allowed := ARRAY[]::text[];    ELSE v_allowed := ARRAY[]::text[];  END CASE;  IF NOT (NEW.status = ANY(v_allowed)) THEN    RAISE EXCEPTION 'Invalid status transition: % -> %', OLD.status, NEW.status      USING ERRCODE = '22023';  END IF;  RETURN NEW;END;$function$;COMMENT ON FUNCTION public.enforce_permission_transitions IS 'Enforces state machine for permissions.status';DO $$DECLARE  trg_table TEXT;BEGIN  SELECT tablename INTO trg_table FROM (    SELECT tgrelid::regclass::text AS tablename    FROM pg_trigger    WHERE tgname = 'trg_permission_state_machine'      AND NOT tgisinternal    ORDER BY tgrelid::regclass::text    LIMIT 1  ) t;  trg_table := COALESCE(trg_table, 'permissions');  EXECUTE 'DROP TRIGGER IF EXISTS trg_permission_state_machine ON public.' || trg_table;END$$;DO $$DECLARE  has_perms BOOLEAN;BEGIN  has_perms := EXISTS (    SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'permissions'  );  IF has_perms THEN    CREATE TRIGGER trg_permission_state_machine      BEFORE UPDATE OF status ON public.permissions      FOR EACH ROW EXECUTE FUNCTION public.enforce_permission_transitions();  ELSIF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'permission_requests') THEN    CREATE TRIGGER trg_permission_state_machine      BEFORE UPDATE OF status ON public.permission_requests      FOR EACH ROW EXECUTE FUNCTION public.enforce_permission_transitions();  END IF;END$$;CREATE SEQUENCE IF NOT EXISTS public.lab_ticket_seq START 1001;CREATE SEQUENCE IF NOT EXISTS public.hostel_ticket_seq START 1001;CREATE SEQUENCE IF NOT EXISTS public.exam_ticket_seq START 1001;CREATE SEQUENCE IF NOT EXISTS public.memo_ticket_seq START 1001;CREATE SEQUENCE IF NOT EXISTS public.staff_leave_ticket_seq START 1001;DO $$BEGIN  IF EXISTS (    SELECT 1 FROM information_schema.columns    WHERE table_schema = 'public' AND table_name = 'permissions'      AND column_name = 'sla_deadline'  ) THEN    IF NOT EXISTS (      SELECT 1 FROM pg_indexes      WHERE schemaname = 'public' AND indexname = 'idx_permissions_sla_pending'    ) THEN      CREATE INDEX idx_permissions_sla_pending        ON public.permissions (sla_deadline)        WHERE status = 'PENDING' AND sla_deadline IS NOT NULL;    END IF;  END IF;END$$;DO $$BEGIN  IF EXISTS (    SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'permissions'  ) THEN    ALTER TABLE public.permissions ENABLE ROW LEVEL SECURITY;  END IF;  IF EXISTS (    SELECT 1 FROM pg_roles WHERE rolname = 'service_role'  ) AND NOT EXISTS (    SELECT 1 FROM pg_policies    WHERE schemaname = 'public' AND tablename = 'permissions'      AND policyname = 'permissions_service_role'  ) THEN    CREATE POLICY permissions_service_role ON public.permissions      FOR ALL TO service_role USING (true) WITH CHECK (true);  END IF;END$$;DO $$BEGIN  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN    ALTER ROLE service_role BYPASSRLS;  END IF;END$$;DO $$DECLARE  cdef   TEXT;  newdef TEXT;  extra  TEXT;  lit    CONSTANT TEXT := '''';BEGIN  SELECT pg_get_constraintdef(c.oid) INTO cdef    FROM pg_constraint c    JOIN pg_class t ON t.oid = c.conrelid   WHERE t.relname = 'audit_logs' AND c.conname = 'audit_logs_action_known' AND c.contype = 'c';  IF cdef IS NULL THEN    RAISE NOTICE 'audit_logs_action_known: constraint not found, nothing to do';    RETURN;  END IF;  IF cdef LIKE '%DELEGATION_CREATED%' AND cdef LIKE '%PERMISSION_HELD_FOR_DOCUMENT%' THEN    RAISE NOTICE 'audit_logs_action_known: new actions already present';    RETURN;  END IF;  WITH candidates AS (    SELECT v.val AS val    FROM (VALUES      ('DELEGATION_CREATED'),      ('PERMISSION_HELD_FOR_DOCUMENT')    ) v(val)  )  SELECT string_agg(lit || a.val || lit || '::character varying', ', ' ORDER BY a.val)    INTO extra    FROM candidates a   WHERE position(lit || a.val || lit || '::character varying' IN cdef) = 0;  IF extra IS NULL THEN    RAISE NOTICE 'audit_logs_action_known: all new actions already present';    RETURN;  END IF;  newdef := replace(cdef, 'ARRAY[', 'ARRAY[' || extra || ',');  IF newdef = cdef THEN    RAISE NOTICE 'audit_logs_action_known: no ARRAY[ anchor found, leaving unchanged';    RETURN;  END IF;  EXECUTE 'ALTER TABLE public.audit_logs DROP CONSTRAINT audit_logs_action_known';  EXECUTE 'ALTER TABLE public.audit_logs ADD CONSTRAINT audit_logs_action_known ' || newdef;  RAISE NOTICE 'audit_logs_action_known: appended missing actions: %', extra;END$$;DO $$DECLARE  has_filename BOOLEAN;  has_checksum BOOLEAN;BEGIN  SELECT EXISTS (    SELECT 1 FROM information_schema.columns    WHERE table_schema = 'public' AND table_name = 'schema_migrations'      AND column_name = 'filename'  ) INTO has_filename;  SELECT EXISTS (    SELECT 1 FROM information_schema.columns    WHERE table_schema = 'public' AND table_name = 'schema_migrations'      AND column_name = 'checksum'  ) INTO has_checksum;  IF has_filename AND has_checksum THEN    INSERT INTO public.schema_migrations (version, filename, applied_at, checksum)    VALUES ('20261116000000', '20261116000000_approver_contract_repair.sql', NOW(),            md5('20261116000000_approver_contract_repair'))    ON CONFLICT (version) DO NOTHING;  ELSIF has_filename THEN    INSERT INTO public.schema_migrations (version, filename, applied_at)    VALUES ('20261116000000', '20261116000000_approver_contract_repair.sql', NOW())    ON CONFLICT (version) DO NOTHING;  ELSE    INSERT INTO public.schema_migrations (version, applied_at)    VALUES ('20261116000000', NOW())    ON CONFLICT (version) DO NOTHING;  END IF;END$$;